INSERT INTO `categories` (`id`, `name`, `slug`, `icon`, `description`, `meta_title`, `meta_description`, `color`, `display_order`) VALUES
(1, 'PDF & Documents', 'pdf-tools', 'fa-file-pdf', 'Merge, split, compress, rotate, watermark, and convert PDF documents quickly and securely without file leaks.', 'Free Online PDF Tools | Merge, Split, Convert & Compress PDF', 'Access high-speed PDF tools online. Convert PDF to images, images to PDF, compress, rotate, merge, and watermark documents for free on ToolsWallet.', '#ef4444', 1),
(2, 'SEO & Web Utilities', 'seo-tools', 'fa-chart-line', 'Audit on-page SEO, generate XML sitemaps, inspect redirects, inspect canonical links, and preview SERP snippets.', 'Free SEO Tools & Website Utilities | Audit, Sitemap & Meta Generator', 'Boost your website ranking with powerful webmaster utilities. Generate sitemaps, robots.txt, schema JSON-LD, meta tags, and audit on-page SEO factors.', '#3b82f6', 2),
(3, 'Social Media Utilities', 'social-tools', 'fa-share-nodes', 'Generate viral captions, optimize image aspect ratios for Instagram and YouTube, grab thumbnails, and preview posts.', 'Free Social Media Tools | Caption Generator, Aspect Ratio & Previews', 'Create engaging social media content. Crop images to Instagram, Story, and YouTube ratios, generate trending hashtags, and preview link cards.', '#ec4899', 3),
(4, 'AI Writing & Text', 'ai-writing', 'fa-wand-magic-sparkles', 'Craft high-converting blog outlines, meta descriptions, summaries, rewrite paragraphs, and analyze grammar.', 'Free AI Writing Tools & Text Utilities | Outline, Rewrite & Summarize', 'Level up your writing with AI-assisted generators. Produce blog outlines, catchy headlines, concise summaries, paraphrased paragraphs, and count words.', '#8b5cf6', 4),
(5, 'Image Tools', 'image-tools', 'fa-image', 'Compress, resize, convert formats, watermark photos, and extract harmonious color palettes right in your browser.', 'Free Online Image Tools | Resize, Compress, Convert & Watermark', 'Fast image optimization and editing. Compress image file size without visual quality loss, resize dimensions, convert between WebP/PNG/JPG, and add watermarks.', '#10b981', 5),
(6, 'Developer Tools', 'developer-tools', 'fa-code', 'Format and validate JSON, encode Base64, generate QR codes, minify HTML/CSS/JS, generate UUIDs, and hash strings.', 'Free Developer Utilities | JSON Formatter, QR Generator, Base64 & Hashes', 'Essential web developer utilities in one wallet. Format JSON with error detection, generate QR codes, encode/decode Base64, pick colors, and compute hashes.', '#06b6d4', 6),
(7, 'Calculators & Math', 'calculators', 'fa-calculator', 'Calculate percentages, loan EMIs with amortization schedules, age differences, discounts, sales taxes, and unit conversions.', 'Free Online Calculators | Loan EMI, Percentage, Age & Unit Converter', 'Make accurate calculations in seconds. Compute monthly loan payments, percentage changes, precise chronological ages, discounts, and convert units.', '#f59e0b', 7);

