INSERT INTO `tools` (`category_id`, `name`, `slug`, `icon`, `short_description`, `description`, `features`, `how_to_use`, `meta_title`, `meta_description`, `meta_keywords`, `badge`, `is_featured`, `is_popular`, `is_trending`, `run_count`, `rating`) VALUES
-- PDF Tools
(1, 'PDF to Images', 'pdf-to-images', 'fa-file-image', 'Extract every page of your PDF document into crisp, high-resolution PNG or JPG images.', 'Convert every single page of your PDF documents into top-grade PNG or JPG pictures. Everything renders right in your browser for absolute privacy and zero server wait time.', 'High DPI rendering;Multiple image formats (PNG, JPG);Batch ZIP download;No file size limit;100% private in-browser rendering', '1. Drag and drop or browse to choose your PDF file.\n2. Pick your desired output format (PNG or JPG).\n3. Click "Render Pages" to extract images.\n4. Download individual page images or the entire ZIP archive.', 'Free PDF to Images Converter Online | ToolsWallet', 'Convert PDF pages to high-quality PNG or JPG images online for free. Fast, secure, and preserves complete document privacy.', 'pdf to image, pdf to png, pdf to jpg, convert pdf, extract pdf pages', 'Popular', 1, 1, 0, 18450, 4.9),
(1, 'Images to PDF', 'images-to-pdf', 'fa-images', 'Combine multiple JPG, PNG, and WebP images into a single professional PDF document.', 'Merge photos, receipts, scans, or graphic designs into a consolidated PDF file. Reorder pages, select page orientation (portrait or landscape), and apply custom margins with zero hassle.', 'Drag & drop image reordering;Custom page margins (None, Small, Normal);Portrait & Landscape orientation;High compression optimization;Instant download', '1. Upload one or multiple images (JPG, PNG, WebP).\n2. Arrange page sequence by dragging cards.\n3. Configure margin and orientation settings.\n4. Click "Generate PDF" to download your combined document.', 'Images to PDF Converter Online Free | ToolsWallet', 'Combine JPG, PNG, and WebP images into a single clean PDF document. Customize margins, orientation, and order effortlessly.', 'images to pdf, jpg to pdf, png to pdf, photo to pdf maker', 'Trending', 1, 1, 1, 23100, 4.9),
(1, 'Merge PDF', 'merge-pdf', 'fa-object-group', 'Combine two or more PDF files into a single organized document in seconds.', 'Quickly assemble multiple PDF files into one clean document. Drag to arrange the files in your preferred sequence and merge them instantly without losing document clarity.', 'Multi-file merge support;Instant page count preview;Custom ordering of input files;Lossless PDF preservation;Secure automated processing', '1. Upload two or more PDF files.\n2. Arrange the files in the order you want them merged.\n3. Click "Merge PDFs".\n4. Save your unified PDF file directly to your device.', 'Merge PDF Files Online for Free | ToolsWallet', 'Combine multiple PDF files into one unified document online. Fast, secure, and completely free on ToolsWallet.', 'merge pdf, combine pdf, join pdf files, online pdf merger', 'Popular', 1, 1, 0, 31200, 4.9),
(1, 'Split PDF', 'split-pdf', 'fa-scissors', 'Extract specific pages or page ranges from large PDF documents into smaller files.', 'Extract custom page ranges (e.g. 1-3, 5, 8-10) or separate every single page into distinct PDF documents without quality degradation.', 'Extract custom page ranges;Individual page separation;Visual page thumbnail picker;Lightning-fast processing;Safe local memory execution', '1. Upload your PDF file.\n2. Enter the page ranges you want to extract (e.g. 1-4, 7).\n3. Click "Split PDF".\n4. Download your trimmed PDF file.', 'Split PDF Online - Extract Pages Free | ToolsWallet', 'Extract specific pages or page ranges from any PDF document quickly and securely on ToolsWallet.', 'split pdf, extract pdf pages, cut pdf, separate pdf', NULL, 0, 1, 0, 14200, 4.8),
(1, 'Compress PDF', 'compress-pdf', 'fa-compress', 'Reduce PDF document file size while preserving readability and vector clarity.', 'Shrink bulky PDF files for quick email attachments or web publishing. Choose between Recommended, Extreme, or Light compression levels.', 'Three tailored compression profiles;Shows exact file size savings;Maintains text clarity;Privacy-safe processing;No watermarks attached', '1. Upload your PDF document.\n2. Select your compression level.\n3. Click "Compress PDF".\n4. Review the space saved and download your optimized file.', 'Compress PDF Online Free - Reduce PDF Size | ToolsWallet', 'Reduce PDF file size online without compromising quality. Perfect for email attachments and web upload limits.', 'compress pdf, reduce pdf size, shrink pdf file, pdf optimizer', 'Popular', 1, 1, 1, 45200, 4.9),
(1, 'Rotate PDF', 'rotate-pdf', 'fa-rotate-right', 'Rotate PDF pages 90, 180, or 270 degrees clockwise or counter-clockwise permanently.', 'Fix upside-down or sideways PDF scans. Rotate all pages at once or adjust specific individual pages with a single click.', 'Rotate all or specific pages;90°, 180°, and 270° orientation;Visual preview before saving;Permanent orientation fix;Instant download', '1. Upload the PDF file you wish to rotate.\n2. Choose the rotation angle (90° right, 90° left, or 180°).\n3. Click "Apply Rotation".\n4. Download the newly oriented PDF.', 'Rotate PDF Pages Online Free | ToolsWallet', 'Rotate sideways or upside-down PDF pages 90, 180, or 270 degrees online for free. Clean, quick, and secure.', 'rotate pdf, turn pdf, flip pdf pages, fix pdf orientation', NULL, 0, 0, 0, 9800, 4.8),
(1, 'Watermark PDF', 'watermark-pdf', 'fa-stamp', 'Add custom text watermarks to your PDF documents with custom opacity, color, and angle.', 'Protect your intellectual property, invoices, contracts, or draft documents by overlaying customizable security watermarks across all pages.', 'Custom text and font size;Rotation angle (0° to 90°);Opacity and color picker;Center or tiled watermark layout;Immediate client download', '1. Upload your PDF document.\n2. Enter your watermark text (e.g., CONFIDENTIAL, DRAFT).\n3. Customize opacity, angle, and font size.\n4. Click "Apply Watermark" and download.', 'Add Watermark to PDF Online Free | ToolsWallet', 'Protect your PDF documents with custom text watermarks. Adjust transparency, angle, and position in seconds.', 'watermark pdf, stamp pdf, add text to pdf, confidential watermark', NULL, 0, 0, 0, 11400, 4.8),

-- SEO Tools
(2, 'XML Sitemap Generator', 'xml-sitemap-generator', 'fa-sitemap', 'Generate search-engine-ready XML sitemaps from URL lists with priorities and change frequencies.', 'Create Google-compliant XML sitemaps in seconds. Input your website URLs, assign change frequency (daily, weekly, monthly) and priority (0.1 to 1.0), and download the valid sitemap.xml file.', 'Supports up to 500 URLs per batch;Custom changefreq and priority;Automatic ISO 8601 lastmod dates;One-click download of sitemap.xml;Syntax-validated XML structure', '1. Enter or paste your website URLs (one per line).\n2. Set default change frequency and priority.\n3. Click "Generate Sitemap".\n4. Copy the XML code or download sitemap.xml to place on your server.', 'Free XML Sitemap Generator Online | ToolsWallet', 'Generate Google-compliant XML sitemaps from your URL list. Set priorities and frequencies for optimal search indexing.', 'xml sitemap generator, create sitemap, google sitemap maker, seo sitemap', 'Popular', 1, 1, 0, 28900, 4.9),
(2, 'Robots.txt Generator & Validator', 'robots-txt-generator', 'fa-robot', 'Create and test a search engine crawler robots.txt file with custom allow and disallow directives.', 'Build clean, search-engine-friendly robots.txt files for Googlebot, Bingbot, and other web crawlers. Easily add disallow rules for admin paths, declare sitemap locations, and validate syntax.', 'Pre-configured search bot directives;Custom Disallow and Allow paths;Sitemap declaration inclusion;Live syntax validator;One-click copy and download', '1. Choose the bots you want to target (All robots, Googlebot, Bingbot).\n2. Add disallowed paths (e.g. /admin/, /private/).\n3. Provide your XML sitemap URL.\n4. Click "Generate Robots.txt" and save the file.', 'Robots.txt Generator & Validator Free | ToolsWallet', 'Generate and validate robots.txt files online. Direct Googlebot, Bingbot, and web crawlers with precision.', 'robots txt generator, robots txt validator, create robots txt, crawler rules', NULL, 0, 1, 0, 15600, 4.8),
(2, 'Meta Tag Generator', 'meta-tag-generator', 'fa-tags', 'Generate SEO meta tags, Open Graph tags, and Twitter Cards with real-time Google and social previews.', 'Ensure your web pages rank prominently and display beautiful link previews across Facebook, LinkedIn, Twitter, and Google search. Real-time SERP preview updates as you type.', 'Standard SEO meta tags (Title, Description, Robots);\nOpen Graph tags (og:title, og:image, og:url);\nTwitter Cards (Summary Large Image);\nReal-time Google SERP preview;Pixel length indicators', '1. Fill in your page title, description, and target URL.\n2. Add your Open Graph image URL.\n3. Review the live Google SERP and Social previews.\n4. Click "Copy Meta Tags" to paste into your HTML <head>.', 'SEO Meta Tag Generator with Live Preview | ToolsWallet', 'Generate complete SEO meta tags, Open Graph, and Twitter Cards with instant Google SERP simulation.', 'meta tag generator, open graph generator, twitter card generator, seo tags', 'Trending', 1, 1, 1, 34200, 4.9),
(2, 'Canonical URL Checker', 'canonical-checker', 'fa-link', 'Check the rel=canonical tag, HTTP headers, and URL consistency for any live webpage.', 'Prevent duplicate content penalties by inspecting the rel=canonical link tag on any public URL. Validates HTTP response codes and verifies that the canonical points to the preferred URL.', 'Deep DOM canonical tag inspection;HTTP Link header canonical checking;SSRF-safe website crawling;Status code and redirect detection;Actionable SEO suggestions', '1. Enter the public URL you want to inspect.\n2. Click "Check Canonical".\n3. View canonical status, HTTP headers, and recommendations.', 'Canonical URL Checker & Validator | ToolsWallet', 'Inspect rel=canonical tags and HTTP headers online. Avoid duplicate content issues and verify SEO best practices.', 'canonical checker, rel canonical, duplicate content checker, canonical tag validator', NULL, 0, 0, 0, 8900, 4.7),
(2, 'Schema JSON-LD Generator', 'schema-generator', 'fa-code-branch', 'Create Google-recommended Structured Data in JSON-LD format for Articles, Products, FAQs, and more.', 'Supercharge your organic CTR with rich snippets in Google Search results. Build schema markup for Articles, FAQs, Local Businesses, Organizations, and Breadcrumbs without writing complex code.', 'Multiple schema types (Article, FAQ, Product, Organization, Breadcrumbs);\nValidates JSON-LD schema syntax;\nGoogle Rich Results compliant;\nOne-click copy to clipboard;\nVisual form builder', '1. Choose your schema type (e.g. FAQ Page, Article, Organization).\n2. Fill out the guided input fields.\n3. View generated JSON-LD script.\n4. Copy and paste into your webpage code.', 'Schema JSON-LD Generator for Google Rich Snippets | ToolsWallet', 'Build Google-compliant Schema.org JSON-LD structured data for Articles, FAQs, Organizations, and Products.', 'schema generator, json ld generator, structured data maker, rich snippet generator', 'Popular', 1, 1, 0, 26700, 4.9),
(2, 'Redirect & HTTP Header Checker', 'redirect-checker', 'fa-arrows-split-up-and-left', 'Trace URL redirect chains, detect 301/302 redirects, and examine all server response headers.', 'Inspect the entire HTTP redirect chain for any link. See intermediate status codes (301 Permanent, 302 Temporary, 307/308) and view all HTTP headers including security flags.', 'Traces up to 10 redirects in sequence;Displays HTTP response codes;Full headers inspector (Server, Cache-Control, HSTS);SSRF protection against internal IPs;Latency measurement per hop', '1. Enter the target web address.\n2. Click "Analyze Redirects".\n3. View the hop-by-hop journey, status codes, and server headers.', 'Redirect Checker & HTTP Headers Inspector | ToolsWallet', 'Trace redirect chains and check HTTP response headers online. Diagnose 301 vs 302 redirects with SSRF security.', 'redirect checker, http header checker, 301 redirect trace, status code checker', NULL, 0, 1, 0, 19800, 4.8),
(2, 'URL Encoder & Decoder', 'url-encoder-decoder', 'fa-percent', 'Encode special characters into RFC 3986 percent-encoding or decode encoded URLs safely.', 'Seamlessly encode or decode URLs and query parameters. Supports UTF-8 encoding, raw URL encoding, component decoding, and automatically extracts query parameters into an organized table.', 'RFC 3986 compliant encoding/decoding;Query string parameter table breakdown;Instant live bidirectional mode;One-click copy button;Handles special characters and emojis', '1. Paste your raw or encoded URL into the text area.\n2. Click "Encode" or "Decode".\n3. View the transformed output and examine the broken-down parameters.', 'URL Encoder & Decoder Online | ToolsWallet', 'Encode or decode URLs and query parameters online for free. Supports UTF-8 percent-encoding and query breakdown.', 'url encoder, url decoder, percent encoding, decode uri component', NULL, 0, 0, 0, 13400, 4.8),
(2, 'On-Page SEO Analyzer', 'seo-analyzer', 'fa-magnifying-glass-chart', 'Audit key on-page SEO signals including Title, Meta, Headings, Word Count, and Image Alt tags.', 'Perform an instant on-page audit of your webpage. Discover missing meta tags, verify H1-H6 heading hierarchy, assess word count, check image accessibility, and receive an SEO health score out of 100.', 'Comprehensive 0-100 SEO health score;Heading hierarchy audit (H1, H2, H3);Meta title & description length assessment;Image alt tag checklist;Internal and external link counting', '1. Enter any public website URL or paste raw HTML.\n2. Click "Run SEO Audit".\n3. Review your SEO score, warnings, and recommended fixes.', 'Free On-Page SEO Analyzer & Website Audit | ToolsWallet', 'Audit your webpage on-page SEO factors for free. Check headings, meta tags, word count, alt attributes, and get a score.', 'on page seo analyzer, website audit tool, seo score checker, page seo audit', 'Popular', 1, 1, 1, 38100, 4.9),
(2, 'SERP Preview Tool', 'serp-preview', 'fa-desktop', 'Simulate how your webpage appears on Google Search results on Desktop and Mobile devices.', 'Optimize your click-through rate (CTR) before publishing. Test title and description lengths with real Google pixel limits, highlight truncations, and toggle between mobile and desktop previews.', 'Pixel-accurate Google SERP simulation;Desktop & Mobile interface toggles;Character and pixel count warnings;Date and URL breadcrumb configuration;Live interactive editing', '1. Enter your page title, meta description, and URL.\n2. Switch between Desktop and Mobile preview modes.\n3. Adjust copy until it fits within Google pixel guidelines without truncation.', 'Google SERP Preview Tool Online | ToolsWallet', 'Preview and test your Google search snippet on desktop and mobile. Avoid title truncation and maximize CTR.', 'serp preview, google snippet preview, meta description preview, search result simulator', NULL, 0, 0, 0, 12700, 4.8),

-- Social Media Tools
(3, 'Instagram Video & Reels Downloader', 'instagram-downloader', 'fa-camera-retro', 'Download Instagram Reels, Videos, Photos, and Stories in 1080p Full HD MP4 with fast direct download links.', 'Save any Instagram content directly to your phone, tablet, or PC without watermarks. Paste any Instagram Reel, Video, Carousel, or Photo link to preview in real-time and download original 1080p HD MP4 video, MP3 audio, or high-res JPG images.', 'Download Instagram Reels in 1080p Full HD;Save Photos and Carousel slideshows;Extract audio and background sound (MP3);Built-in responsive video preview player;100% Free with unlimited downloads;No login or password required', '1. Open Instagram and copy the share link of any Reel, Video, or Photo.\n2. Paste the link into the download box above.\n3. Click "Get Download Links" to fetch the media preview.\n4. Click "Download Video (HD MP4)" or "Download Photo" to save it immediately.', 'Instagram Video & Reels Downloader - Free Online HD Download | ToolsWallet', 'Download Instagram Reels, Videos, Stories, and Photos online for free in 1080p Full HD. Fast, secure Instagram media downloader with direct download links.', 'instagram downloader, download instagram reels, save instagram video, ig video downloader, instagram photo downloader', 'Hot', 1, 1, 1, 68400, 4.9),
(3, 'YouTube Video & MP3 Downloader', 'youtube-downloader', 'fa-play', 'Download YouTube videos in 1080p, 720p HD MP4 and convert to 320kbps MP3 audio with instant download buttons.', 'The ultimate free YouTube video converter and downloader. Supports standard YouTube videos, Shorts, and mobile links. Watch video previews with the integrated player, select 1080p Full HD, 720p HD, or 480p MP4, or download studio-grade 320kbps MP3 audio.', '1080p Full HD and 720p HD MP4 video downloads;High bitrate 320kbps MP3 audio converter;Full support for YouTube Shorts and mobile links;Built-in responsive video player;Ultra HD 1080p thumbnail downloader;Instant direct file download without waiting queues', '1. Copy any YouTube video link or Shorts URL from the YouTube app or website.\n2. Paste the URL into the search field above.\n3. Click "Convert & Download" to preview options.\n4. Choose your preferred quality (1080p, 720p MP4 or 320kbps MP3) and click Download.', 'Free YouTube Downloader - Download 1080p Video & MP3 Online | ToolsWallet', 'Download YouTube videos in 1080p, 720p HD MP4 and convert to 320kbps MP3 audio for free. Works with YouTube Shorts and mobile links on ToolsWallet.', 'youtube downloader, download youtube video, convert youtube to mp3, youtube shorts downloader, 1080p youtube download', 'Trending', 1, 1, 1, 84200, 4.9),
(3, 'Caption & Hashtag Generator', 'caption-hashtag-generator', 'fa-hashtag', 'Generate compelling social media hooks, captions, and curated hashtags for Instagram, TikTok & LinkedIn.', 'Overcome writer block with engaging social media captions and targeted hashtags categorized by industry: Travel, Tech, Fitness, Food, Business, Fashion, and Motivation.', 'Platform presets (Instagram, TikTok, LinkedIn, X);\nTone selection (Professional, Casual, Witty, Inspiring);\nCurated niche hashtags with copy buttons;\nCharacter count limits per platform;Emoji integration', '1. Choose your platform and industry topic.\n2. Select your desired tone.\n3. Click "Generate Caption & Hashtags".\n4. Copy the caption directly to your clipboard.', 'Social Media Caption & Hashtag Generator | ToolsWallet', 'Generate viral captions and trending hashtags for Instagram, TikTok, LinkedIn, and X in seconds.', 'caption generator, hashtag generator, instagram captions, tiktok hashtags', 'Popular', 1, 1, 1, 29400, 4.9),
(3, 'Image Aspect-Ratio Converter', 'aspect-ratio-converter', 'fa-crop', 'Crop and resize images to standard social media dimensions for Instagram, YouTube, and TikTok.', 'Ensure your graphics look flawless across every social network without awkward cropping. Convert any photo to 1:1 (Square), 4:5 (Portrait), 9:16 (Stories/Reels), or 16:9 (YouTube banner/thumbnail).', 'Social platform presets (Instagram Post, Story, YouTube, Twitter);\nInteractive canvas cropping with zoom;\nCustom aspect ratio selector;\nHigh quality export (PNG, JPG, WebP);\nNo quality loss', '1. Upload your photo or graphic.\n2. Choose your target social ratio preset.\n3. Reposition the crop window.\n4. Click "Export Cropped Image" to download.', 'Social Media Aspect Ratio Converter & Cropper | ToolsWallet', 'Resize and crop images to perfect dimensions for Instagram, YouTube, TikTok, and Twitter headers.', 'aspect ratio converter, social media image cropper, instagram photo resizer, 16 9 cropper', 'Trending', 1, 1, 0, 21500, 4.8),
(3, 'YouTube Thumbnail & Metadata Viewer', 'youtube-thumbnail-grabber', 'fa-youtube', 'View and download high-resolution HD YouTube thumbnails and inspect public video metadata.', 'Extract ultra-high-definition (1080p MaxResDefault, HQ, MQ) thumbnails from any public YouTube video. View video ID, embed code, and title preview without third-party bloat.', 'Downloads 1080p MaxRes, 720p HD, and Standard thumbnails;\nInstant video title and channel preview;\nClean one-click image download buttons;\nSafe public oEmbed integration;\nResponsive video embed player', '1. Paste any YouTube video link or Shorts URL.\n2. Click "Fetch Thumbnail".\n3. Preview all available resolution qualities and click "Download".', 'YouTube Thumbnail Downloader & Metadata Viewer | ToolsWallet', 'Download HD, 4K, and 1080p YouTube video thumbnails for free. Instant, high-resolution preview on ToolsWallet.', 'youtube thumbnail downloader, grab youtube thumbnail, youtube metadata viewer, maxres thumbnail', 'Popular', 1, 1, 0, 39700, 4.9),
(3, 'Social Post Previewer', 'social-post-previewer', 'fa-id-card', 'Preview how your link and Open Graph image will appear when shared across social networks.', 'Verify your Open Graph image, headline, and domain attribution before sharing. Accurately simulates link preview cards for Facebook, X/Twitter, LinkedIn, and Discord.', 'Multi-platform live simulation (Twitter, Facebook, LinkedIn, Discord);\nCustom title, description, and image test fields;\nInspects character cutoff;\nReal-time responsive card layout', '1. Enter the title, description, and image URL (or upload a local picture).\n2. Toggle through the social media platform tabs.\n3. Refine your text until the cards look pixel-perfect.', 'Social Post & Open Graph Previewer | ToolsWallet', 'Preview how your web links and images look when shared on Twitter, Facebook, and LinkedIn.', 'social post preview, open graph card preview, twitter card preview, share preview', NULL, 0, 0, 0, 11200, 4.8),

-- AI Writing & Text Tools
(4, 'Blog Post Outline Generator', 'blog-outline-generator', 'fa-list-check', 'Create comprehensive, SEO-optimized blog article outlines with introduction hooks, H2s, H3s, and conclusions.', 'Break through writer block in seconds. Input your article topic and target audience to produce an in-depth, structured outline complete with subheadings, talking points, and call-to-action ideas.', 'Generates H2 and H3 subheadings;\nIncludes compelling introductory hooks;\nActionable bullet points for each section;\nExport to Markdown or Plain Text;\nCustomizable article depth and tone', '1. Enter your target blog topic or keyword.\n2. Select your desired depth (Standard or In-Depth).\n3. Click "Generate Blog Outline".\n4. Copy or download the structured outline in Markdown.', 'AI Blog Post Outline Generator Free | ToolsWallet', 'Generate SEO-friendly blog outlines in seconds. Includes H2s, H3s, talking points, and conclusions.', 'blog outline generator, ai article outline, content structure maker, blog post planner', 'Popular', 1, 1, 1, 31800, 4.9),
(4, 'Title & Meta Description Generator', 'title-meta-generator', 'fa-heading', 'Generate 10 high-CTR headlines and compelling meta descriptions tailored for search engines.', 'Boost your organic clicks with enticing headlines and search-optimized meta descriptions. Generates click-worthy variations including How-Tos, List posts, Questions, and Power Word titles.', '10 unique headline suggestions per query;\nMatched meta descriptions within 155 characters;\nCategorized by angle (How-To, Listicle, Benefit, Curiosity);\nOne-click copy for each suggestion', '1. Enter your primary topic or product focus.\n2. Click "Generate Titles & Descriptions".\n3. Browse the creative suggestions and copy your favorite.', 'AI Headline & Meta Description Generator | ToolsWallet', 'Generate high-converting headlines and SEO meta descriptions in seconds with ToolsWallet.', 'headline generator, title generator, meta description generator, catchy titles', NULL, 0, 1, 0, 17900, 4.8),
(4, 'Text Summarizer', 'text-summarizer', 'fa-compress-arrows-alt', 'Condense lengthy articles, essays, and reports into concise summaries or bullet-point takeaways.', 'Extract the core essence from any long piece of content. Adjust the summary length slider to get a quick TL;DR, a 25% overview, or an itemized list of key takeaways.', 'Adjustable summary ratio (15%, 30%, 50%);\nKey bullet points extraction mode;\nSentence significance scoring algorithm;\nWord count reduction stats comparison;\nClean copy output', '1. Paste your long article, document, or essay.\n2. Adjust the summary length slider or pick Bullet Points.\n3. Click "Summarize Text".\n4. Read and copy your concise summary.', 'Text Summarizer Online Free - Summarize Articles | ToolsWallet', 'Summarize long texts, essays, and articles into clear summaries or key bullet points online.', 'text summarizer, article summarizer, summarize text online, tldr generator', 'Popular', 1, 1, 0, 41200, 4.9),
(4, 'Text Rewriter & Paraphraser', 'text-rewriter', 'fa-repeat', 'Paraphrase sentences and rewrite paragraphs to improve flow, vocabulary, and readability.', 'Refresh existing content while preserving original meaning. Rephrase complex sentences, eliminate repetitive words, and enhance overall sentence variety.', 'Multiple rewrite styles (Fluency, Standard, Creative, Professional);\nSide-by-side original vs rewritten comparison;\nSynonym highlights;\nOne-click copy to clipboard', '1. Paste your source text.\n2. Select your rewriting mode.\n3. Click "Rewrite Text".\n4. Review the paraphrased version and copy the result.', 'Text Rewriter & Paraphraser Online Free | ToolsWallet', 'Rewrite sentences and paragraphs online for free. Improve clarity and vocabulary effortlessly.', 'text rewriter, article rewriter, paraphrasing tool, sentence rephraser', 'Trending', 1, 1, 1, 36500, 4.8),
(4, 'Grammar & Readability Checker', 'grammar-checker', 'fa-spell-check', 'Identify common grammatical errors, passive voice, wordiness, and compute readability scores.', 'Enhance your writing quality with instant readability metrics. Computes Flesch-Kincaid Reading Ease, reading grade level, highlights passive constructions, and flags lengthy run-on sentences.', 'Flesch Reading Ease & Grade Level metrics;\nPassive voice detection;\nFlagging of lengthy/complex sentences;\nEstimated reading & speaking time;\nClean correction tips', '1. Type or paste your document text.\n2. Click "Analyze Grammar & Readability".\n3. Review your readability score and highlighted writing suggestions.', 'Grammar & Readability Checker Online | ToolsWallet', 'Analyze grammar, passive voice, and readability scores online. Enhance document clarity on ToolsWallet.', 'grammar checker, readability score, flesch kincaid checker, passive voice detector', NULL, 0, 1, 0, 22100, 4.8),
(4, 'Product Description Generator', 'product-description-generator', 'fa-bag-shopping', 'Create persuasive, sales-driven e-commerce product descriptions with features and benefits.', 'Craft compelling product copy that drives conversions on Amazon, Shopify, or WooCommerce. Automatically converts product features into consumer benefits with a strong call-to-action.', 'E-commerce focused structure (Hook, Features, Benefits, CTA);\nTone options (Luxury, Friendly, Technical, Minimalist);\nBullet points formatting;\nOne-click copy', '1. Enter the product name, category, and core features.\n2. Select your brand tone.\n3. Click "Generate Product Description".\n4. Copy the sales copy directly to your store catalog.', 'Product Description Generator for E-Commerce | ToolsWallet', 'Create engaging product descriptions that boost sales for Shopify, Amazon, and WooCommerce.', 'product description generator, ecommerce copywriter, product copy maker', NULL, 0, 0, 0, 14800, 4.8),
(4, 'Word & Character Counter', 'word-counter', 'fa-calculator', 'Count words, characters, sentences, paragraphs, and estimate reading time in real time.', 'A modern, distraction-free word counter with live updates. Calculates total characters (with and without spaces), word count, average sentence length, reading time (200 wpm), and keyword density.', 'Real-time calculation as you type;\nCharacters with & without spaces;\nSentence & paragraph counts;\nReading & speaking time estimates;\nTop 5 keyword density table', '1. Type or paste your text into the editor.\n2. View live statistics updated instantly without clicking anything.\n3. Check keyword density and reading time.', 'Word & Character Counter Online | ToolsWallet', 'Count words, characters, sentences, and reading time in real time. Free word counter on ToolsWallet.', 'word counter, character counter, text length counter, reading time calculator', 'Popular', 1, 1, 0, 52300, 4.9),
(4, 'Case Converter', 'case-converter', 'fa-font', 'Convert text between UPPERCASE, lowercase, Title Case, camelCase, snake_case, and kebab-case.', 'Transform text case in one click. Useful for programmers, copywriters, and data cleaners needing to reformat headings, code variables, or URLs.', 'Supports UPPERCASE, lowercase, Title Case, Sentence case;\nDeveloper cases: camelCase, PascalCase, snake_case, kebab-case, CONSTANT_CASE;\nOne-click copy and download', '1. Paste your text into the input box.\n2. Click your desired case conversion button.\n3. Copy the converted text to your clipboard.', 'Text Case Converter Online | Title Case, camelCase & UPPERCASE', 'Convert text between uppercase, lowercase, title case, camelCase, and snake_case online for free.', 'case converter, title case, uppercase converter, lowercase, camelcase', NULL, 0, 1, 0, 24100, 4.9),
(4, 'Lorem Ipsum Generator', 'lorem-ipsum-generator', 'fa-paragraph', 'Generate customizable placeholder dummy text in paragraphs, sentences, or bulleted lists.', 'Generate clean placeholder typography for mockups, prototypes, and web design. Choose between standard Latin Lorem Ipsum, modern english dummy text, and configure HTML tag wraps.', 'Paragraphs, sentences, and words generation;\nOptional <p> or <li> HTML tag wrapping;\nClassic Cicero Latin text;\nInstant copy and download', '1. Choose output type (Paragraphs, Sentences, or Words).\n2. Set the count quantity.\n3. Click "Generate Dummy Text" and copy.', 'Lorem Ipsum Generator Online | Dummy Text for Designers', 'Generate custom Lorem Ipsum placeholder dummy text for web design and mockups in seconds.', 'lorem ipsum generator, dummy text generator, placeholder text, latin dummy copy', NULL, 0, 0, 0, 16300, 4.8),
(4, 'Text Diff & Compare Tool', 'text-diff', 'fa-code-compare', 'Compare two texts side-by-side or inline to spot differences, additions, and deletions.', 'Easily compare two drafts, code snippets, or text files. Visual color highlights clearly indicate added lines (green), removed lines (red), and modified characters.', 'Side-by-side and inline unified diff views;\nWord-by-word and character-level differences;\nClean syntax highlighting;\nDiff statistics summary', '1. Paste original text in the left panel and modified text in the right panel.\n2. Click "Compare Texts".\n3. Review highlighted differences side-by-side.', 'Text Diff & Compare Tool Online | Spot Text Differences', 'Compare two texts side-by-side or inline to identify additions, deletions, and differences.', 'text diff tool, compare text online, string difference checker, diff viewer', NULL, 0, 1, 0, 19400, 4.8),

-- Image Tools
(5, 'Image Resizer', 'image-resizer', 'fa-up-right-and-down-left-from-center', 'Resize images by pixel dimensions or percentage while maintaining original aspect ratio.', 'Change picture dimensions in your browser with zero quality degradation. Lock aspect ratio, select percentage scaling, or input custom width and height in pixels.', 'Custom pixel width and height scaling;\nPercentage scaling slider (25%, 50%, 75%);\nLock aspect ratio toggle;\nHigh-quality bicubic interpolation;\nInstant download with file size preview', '1. Upload your image (PNG, JPG, WebP).\n2. Specify your target dimensions or percentage.\n3. Click "Resize Image".\n4. Download the resized image immediately.', 'Online Image Resizer Free - Resize Photos | ToolsWallet', 'Resize images by exact pixels or percentage online. Maintain aspect ratio and download in seconds.', 'image resizer, resize image, photo resizer, change image dimensions', 'Popular', 1, 1, 1, 37800, 4.9),
(5, 'Image Compressor', 'image-compressor', 'fa-file-zipper', 'Compress JPG, PNG, and WebP images up to 80% without noticeable loss in visual quality.', 'Speed up your website loading speed by compressing oversized photos. Move the quality slider, preview the compressed image in real time, and see the exact file size reduction.', 'Interactive quality slider (10% to 100%);\nReal-time before-and-after size comparison;\nSupports PNG, JPG, and WebP formats;\n100% private in-browser compression;\nBatch compression ready', '1. Drag and drop your image file.\n2. Adjust the compression quality slider.\n3. Review the file size savings percentage.\n4. Click "Download Compressed Image".', 'Image Compressor Online Free - Compress JPG, PNG & WebP', 'Compress images online up to 80% without quality loss. Fast, free, and secure photo compression.', 'image compressor, compress jpg, compress png, reduce image size, webp compress', 'Popular', 1, 1, 1, 48900, 4.9),
(5, 'Image Format Converter', 'image-converter', 'fa-arrows-rotate', 'Convert images between PNG, JPG, WebP, GIF, BMP, and SVG formats in high quality.', 'Seamlessly convert pictures between popular image formats. Transform bulky PNGs to modern lightweight WebP, convert JPGs to PNG with transparency, and optimize graphics for the web.', 'Converts between PNG, JPG, WebP, BMP, and GIF;\nConfigurable background fill for transparent images;\nLossless conversion options;\nInstant browser download', '1. Upload the image you want to convert.\n2. Select your target output format.\n3. Click "Convert Image".\n4. Save your new image file to your device.', 'Image Format Converter Online | PNG, JPG, WebP & GIF', 'Convert images between JPG, PNG, WebP, GIF, and BMP formats online for free on ToolsWallet.', 'image converter, png to jpg, jpg to webp, webp to png, convert photo format', 'Trending', 1, 1, 0, 31400, 4.9),
(5, 'Image Watermark Tool', 'image-watermark', 'fa-shield-halved', 'Protect your photographs by stamping custom text watermarks with custom position and opacity.', 'Prevent photo theft and brand your visual assets before publishing on social media or client portfolios. Add custom text, adjust opacity, choose font size, and set position.', 'Text watermark with custom font and size;\nOpacity transparency slider (10% to 100%);\n9-point position grid (Center, Corners, Edges);\nAngle rotation control;\nInstant export', '1. Upload the image to watermark.\n2. Type your copyright or brand text.\n3. Choose watermark position and transparency.\n4. Click "Apply & Download Image".', 'Add Watermark to Images Online Free | ToolsWallet', 'Watermark photos and graphics online. Add custom text with adjustable opacity, angle, and position.', 'image watermark, watermark photos, add copyright to image, photo watermarker', NULL, 0, 0, 0, 13700, 4.8),
(5, 'Color Palette Extractor', 'palette-extractor', 'fa-palette', 'Extract dominant colors and create a harmonious hex palette from any uploaded picture.', 'Extract the underlying color scheme from photos, UI screenshots, or nature photography. Generates dominant HEX, RGB, and HSL codes with one-click copy buttons.', 'Extracts 6 dominant harmonic colors;\nDisplays HEX, RGB, and HSL values;\nOne-click copy for each swatch;\nExport palette as CSS variables or image;\nInstant canvas analysis', '1. Upload any photo, graphic, or UI mockup.\n2. View the automatically generated 6-color palette.\n3. Click any color swatch to copy its HEX code.', 'Color Palette Extractor from Image | ToolsWallet', 'Extract harmonious color palettes and HEX codes from any uploaded image in seconds.', 'color palette extractor, image color picker, extract colors from image, photo color palette', NULL, 0, 1, 0, 16900, 4.8),

-- Developer Tools
(6, 'JSON Formatter & Validator', 'json-formatter', 'fa-brackets-curly', 'Beautify, minify, and validate JSON data with clear syntax error indicators and tree view.', 'Clean up messy JSON payloads. Formats with 2 or 4 space indents, collapses to minified single-line JSON, and pinpoints syntax errors with line numbers and character positions.', '2 or 4 space indentation formatting;\nSingle-line JSON minification;\nReal-time syntax validation with line errors;\nInteractive collapsible tree view;\nOne-click copy and JSON file download', '1. Paste your raw JSON into the editor.\n2. Click "Beautify" to format or "Minify" to compact.\n3. If errors exist, view the exact error location and fix them.\n4. Copy or download your clean JSON.', 'Free JSON Formatter & Validator Online | ToolsWallet', 'Format, validate, and minify JSON data with line error detection and tree view on ToolsWallet.', 'json formatter, json validator, beautify json, minify json, format json online', 'Popular', 1, 1, 1, 62100, 4.9),
(6, 'Base64 Encoder & Decoder', 'base64-converter', 'fa-binary', 'Encode text or files into Base64 format and decode Base64 strings back to original content.', 'Convert plain text, images, or documents to Base64 data strings for embeddable HTML, CSS, or API transmission. Also decodes Base64 data strings with live preview.', 'Text to Base64 and Base64 to Text;\nImage & file to Base64 Data URI converter;\nLive image preview for decoded data URIs;\nSafe UTF-8 handling;\nInstant copy and download', '1. Select mode: "Text" or "File".\n2. Input your text or upload a file.\n3. Click "Encode" or "Decode".\n4. Copy your Base64 string or download the decoded file.', 'Base64 Encoder & Decoder Online | ToolsWallet', 'Encode text and files to Base64 or decode Base64 strings with live image preview online.', 'base64 encoder, base64 decoder, base64 image converter, base64 data uri', 'Popular', 1, 1, 0, 33400, 4.9),
(6, 'QR Code Generator', 'qr-code-generator', 'fa-qrcode', 'Generate customized QR codes for URLs, WiFi, Contact vCards, and Plain Text with custom colors.', 'Create high-resolution QR codes that scan reliably on iOS and Android cameras. Customize foreground and background colors, adjust pixel size, and download as PNG or SVG.', 'Supports URLs, Plain Text, WiFi networks, and vCards;\nCustom foreground and background color pickers;\nAdjustable resolution (200px to 1000px);\nHigh error correction rate;\nInstant PNG download', '1. Choose your QR data type (URL, Text, or WiFi).\n2. Enter the data details.\n3. Customize colors if desired.\n4. Click "Download QR Code" to save the image.', 'Free QR Code Generator Online with Colors | ToolsWallet', 'Create custom QR codes for websites, WiFi, and contact cards with custom colors and instant download.', 'qr code generator, make qr code, create qr code online, free qr maker', 'Popular', 1, 1, 1, 57400, 4.9),
(6, 'Color Picker & Converter', 'color-picker', 'fa-eye-dropper', 'Interactive color picker with instant conversion between HEX, RGB, HSL, HSV, and CMYK.', 'Inspect and convert colors across all web and print standards. Features an eye-friendly color canvas, hex inputs, and WCAG 2.1 AA/AAA contrast ratio checker against white and black.', 'Converts HEX, RGB, HSL, HSV, and CMYK;\nWCAG AA and AAA accessibility contrast checker;\nGenerates complementary, analogous, and triadic shades;\nOne-click copy for CSS code', '1. Select a color using the visual picker or enter a HEX code.\n2. View corresponding RGB, HSL, and CMYK codes.\n3. Check WCAG contrast accessibility.\n4. Click any format to copy its CSS value.', 'Color Picker & Converter (HEX, RGB, HSL) | ToolsWallet', 'Pick colors and convert between HEX, RGB, HSL, and CMYK with WCAG contrast verification.', 'color picker, hex to rgb, rgb to hsl, color converter, wcag contrast checker', NULL, 0, 1, 0, 21800, 4.8),
(6, 'HTML Minifier & Formatter', 'html-minifier', 'fa-file-code', 'Minify HTML code to reduce file size or beautify messy HTML with clean indents.', 'Compress HTML templates and landing pages by stripping unnecessary whitespace, blank lines, and comments. Or switch to Beautify mode to restore clean indentation.', 'Removes HTML comments and extra whitespace;\nBeautify mode with customizable 2/4 spaces;\nCalculates exact byte size savings;\nPreserves pre/code tags;\nOne-click copy', '1. Paste your HTML code into the input area.\n2. Click "Minify HTML" to compress or "Beautify HTML" to format.\n3. Review size savings and copy the output.', 'HTML Minifier & Beautifier Online | ToolsWallet', 'Minify HTML code to boost page speed or format messy HTML with clean indents for free.', 'html minifier, minify html, beautify html, html compressor, html formatter', NULL, 0, 0, 0, 15900, 4.8),
(6, 'CSS Minifier & Formatter', 'css-minifier', 'fa-css3-alt', 'Compress CSS stylesheets by removing whitespace and comments or beautify CSS rules.', 'Optimize your stylesheet loading performance. Strips block comments, collapses semicolon spacing, and compacts color definitions. Or format into clean, readable CSS.', 'Strips comments, blank lines, and redundant semicolons;\nBeautify mode for structured rule indentation;\nByte reduction percentage calculator;\nSafe CSS preservation;\nOne-click copy', '1. Paste your CSS rules into the editor.\n2. Click "Minify CSS" to compress or "Beautify CSS" to format.\n3. Copy the optimized CSS directly to your stylesheet.', 'CSS Minifier & Beautifier Online | ToolsWallet', 'Compress CSS stylesheets for fast web loading or format CSS rules cleanly on ToolsWallet.', 'css minifier, minify css, beautify css, css compressor, css formatter', NULL, 0, 1, 0, 18700, 4.8),
(6, 'JavaScript Minifier', 'js-minifier', 'fa-js', 'Minify JavaScript code to reduce bundle size, remove comments, and speed up script execution.', 'Safely compress JS scripts by stripping inline and block comments and trimming unnecessary spaces and line breaks for faster browser load times.', 'Removes single-line and multi-line comments;\nTrims excess indentation and empty lines;\nDisplays compression ratio statistics;\nOne-click copy and download', '1. Paste your JavaScript code.\n2. Click "Minify JavaScript".\n3. Copy the minified script code.', 'JavaScript Minifier Online Free | ToolsWallet', 'Minify JavaScript code online to reduce file size and speed up script loading for free.', 'js minifier, javascript minifier, minify js, compress javascript', NULL, 0, 0, 0, 17200, 4.8),
(6, 'UUID & GUID Generator', 'uuid-generator', 'fa-fingerprint', 'Generate random RFC 4122 Version-4 UUIDs in bulk with uppercase, lowercase, and hyphen options.', 'Generate cryptographically strong random UUIDs (Universally Unique Identifiers) and GUIDs for database keys, session IDs, and software development testing.', 'RFC 4122 Version-4 compliant generator;\nBulk generation up to 100 UUIDs at once;\nUppercase or lowercase formatting toggle;\nHyphens toggle (with or without dashes);\nOne-click copy all', '1. Select the quantity of UUIDs to generate (1 to 100).\n2. Choose options (Hyphens, Uppercase).\n3. Click "Generate UUIDs".\n4. Copy the UUID list with one click.', 'UUID & GUID Generator Online (v4) | ToolsWallet', 'Generate random RFC 4122 v4 UUIDs and GUIDs in bulk online. Free, fast, and cryptographically secure.', 'uuid generator, guid generator, random uuid, rfc 4122, bulk uuid', NULL, 0, 0, 0, 14300, 4.8),
(6, 'Hash & Checksum Generator', 'hash-generator', 'fa-shield', 'Generate MD5, SHA-1, SHA-256, SHA-512, and CRC32 cryptographic hashes from any text.', 'Compute secure cryptographic checksums and hashes for password validation, integrity verification, and digital signatures. Supports standard hashing algorithms and HMAC keys.', 'Computes MD5, SHA-1, SHA-256, and SHA-512 hashes simultaneously;\nSupports optional secret HMAC key;\nUppercase and lowercase hash display;\nOne-click copy per hash output;\nSafe client-side execution', '1. Type or paste your source text in the input box.\n2. Optionally enter an HMAC secret key.\n3. View generated MD5, SHA-1, SHA-256, and SHA-512 hashes in real time.\n4. Click to copy any hash.', 'Cryptographic Hash Generator (MD5, SHA-256, SHA-512) | ToolsWallet', 'Generate MD5, SHA-1, SHA-256, and SHA-512 hashes online in real time on ToolsWallet.', 'hash generator, md5 hash, sha256 generator, sha512 generator, checksum tool', 'Trending', 1, 1, 0, 27600, 4.9),
(6, 'Markdown to HTML Converter', 'markdown-to-html', 'fa-markdown', 'Live split-screen Markdown editor with real-time GitHub-flavored preview and clean HTML export.', 'Write documentation, READMEs, or blog articles with instant side-by-side rendering. Supports tables, code blocks with syntax styling, blockquotes, checklists, and one-click HTML copy.', 'Live split-screen editing with synchronized scroll;\nGitHub Flavored Markdown (GFM) support;\nTable, task list, and blockquote rendering;\nOne-click copy of compiled HTML;\nDownload as .html or .md', '1. Type your Markdown on the left panel.\n2. Watch the live rendered preview update on the right.\n3. Click "Copy HTML" to get the raw HTML markup.', 'Markdown to HTML Converter & Live Previewer | ToolsWallet', 'Write Markdown with real-time GitHub-flavored preview and export clean HTML markup instantly.', 'markdown to html, markdown previewer, markdown editor online, convert md to html', NULL, 0, 1, 0, 19900, 4.8),

-- Calculators & Math Tools
(7, 'Percentage Calculator', 'percentage-calculator', 'fa-percent', 'Solve all common percentage problems: percentage of a number, percentage increase, and decrease.', 'Solve everyday percentage math in seconds. Calculates: (1) What is X% of Y? (2) X is what percentage of Y? (3) What is the percentage increase/decrease from X to Y?', 'Three distinct calculation modes;\nStep-by-step formula explanations;\nVisual percentage progress bars;\nInstant real-time calculations;\nMobile-friendly number inputs', '1. Choose your calculation mode from the tabs.\n2. Enter the two numbers.\n3. View the exact result with detailed step-by-step calculation.', 'Free Percentage Calculator Online | ToolsWallet', 'Calculate percentages, percentage increases, and percentage decreases online in seconds.', 'percentage calculator, percent increase, percent of number, calculate percentage', 'Popular', 1, 1, 1, 41700, 4.9),
(7, 'Age & Date Difference Calculator', 'age-calculator', 'fa-calendar-days', 'Calculate your exact age in years, months, days, hours, and minutes with next birthday countdown.', 'Determine exact chronological age or find the difference between two arbitrary dates. Calculates total years, months, days, weeks, total hours, and shows days remaining until the next birthday.', 'Exact age in Years, Months, and Days;\nTotal breakdown in Days, Hours, and Minutes;\nCountdown timer to next birthday with weekday indicator;\nZodiac sign calculator;\nDate difference comparison mode', '1. Enter your Date of Birth.\n2. Click "Calculate Age".\n3. View your detailed age breakdown and next birthday countdown.', 'Age Calculator Online - Exact Age in Years & Days | ToolsWallet', 'Calculate exact chronological age in years, months, days, and hours with birthday countdown.', 'age calculator, calculate age, date difference calculator, exact age finder', 'Popular', 1, 1, 0, 49800, 4.9),
(7, 'Loan & EMI Calculator', 'loan-emi-calculator', 'fa-money-bill-wave', 'Calculate monthly EMI, total interest, and visualize a month-by-month loan amortization schedule.', 'Plan home loans, car loans, or personal financing. Enter loan principal amount, annual interest rate, and tenure in years to compute exact monthly EMI, total interest, and total payable amount.', 'Monthly EMI calculation with interactive sliders;\nTotal interest vs principal ratio pie chart breakdown;\nComplete year-by-year amortization table;\nPrintable loan schedule;\nReal-time recalculation', '1. Enter loan amount, annual interest rate (%), and tenure (years).\n2. Review your monthly EMI and total interest payable.\n3. Expand the amortization schedule to see monthly principal vs interest breakdown.', 'Loan & EMI Calculator with Amortization Schedule | ToolsWallet', 'Calculate monthly loan EMI and total interest with detailed amortization schedule for free.', 'loan emi calculator, calculate emi, mortgage calculator, loan payment calculator', 'Popular', 1, 1, 1, 38600, 4.9),
(7, 'Discount & Sales Tax Calculator', 'discount-calculator', 'fa-tag', 'Calculate final price after discounts and sales tax with total savings breakdown.', 'Quickly find how much money you save during sales. Enter original price, discount percentage (or double discount), and optional sales tax/VAT to get final cost and total savings.', 'Supports single and double stacked discounts;\nOptional sales tax / VAT addition;\nClear savings summary badge;\nInstant real-time calculation', '1. Enter the original product price.\n2. Enter the discount percentage.\n3. Optionally enter sales tax rate.\n4. View your final price and exact money saved.', 'Discount & Sales Tax Calculator | ToolsWallet', 'Calculate final prices after discount and sales tax. Find your exact savings instantly.', 'discount calculator, sales tax calculator, calculate discount, sale price calculator', NULL, 0, 0, 0, 18200, 4.8),
(7, 'Unit Converter', 'unit-converter', 'fa-scale-balanced', 'Convert between Length, Weight, Temperature, Area, Speed, and Digital Storage units instantly.', 'A fast, comprehensive unit converter covering metric and imperial measurements. Seamlessly convert meters to feet, kilograms to pounds, Celsius to Fahrenheit, and gigabytes to megabytes.', '6 essential unit categories (Length, Weight, Temp, Area, Speed, Storage);\nReal-time bidirectional conversion;\nComprehensive metric and imperial units;\nPrecision decimal control;\nOne-click swap units button', '1. Select the unit category (e.g. Length, Weight, Temperature).\n2. Pick the "From" and "To" units.\n3. Type a value to see the converted result update instantly.', 'Universal Unit Converter Online | Length, Weight, Temperature', 'Convert units of length, weight, temperature, speed, area, and digital storage for free.', 'unit converter, length converter, weight converter, metric to imperial, unit conversion', 'Trending', 1, 1, 1, 32900, 4.9);

