INSERT INTO `faqs` (`id`, `tool_slug`, `category_slug`, `question`, `answer`, `display_order`) VALUES
(1, NULL, NULL, 'Is ToolsWallet completely free to use?', 'Yes, 100%! All tools on ToolsWallet are completely free without any subscriptions, hidden fees, or daily usage caps.', 1),
(2, NULL, NULL, 'Do I need to create an account or log in to use the tools?', 'No registration or login is required. You can access every single tool immediately, directly in your browser without entering personal information.', 2),
(3, NULL, NULL, 'Are my uploaded files and data secure and private?', 'Absolutely. Most of our tools (such as PDF processing, Image compression, JSON formatting, and QR code generation) execute client-side directly in your browser. Any temporary files processed server-side are automatically wiped from our servers immediately after processing.', 3),
(4, NULL, NULL, 'Can I use ToolsWallet on mobile devices and tablets?', 'Yes. ToolsWallet is engineered mobile-first with a fully responsive interface optimized for smartphones, tablets, laptops, and desktop computers.', 4),
(5, NULL, NULL, 'How can I report a bug or suggest a new tool?', 'We are constantly adding new utilities. You can reach out through our contact page or footer link with any tool suggestions or feedback.', 5),

-- PDF Tool FAQs
(6, 'pdf-to-images', 'pdf-tools', 'Does this tool preserve the original quality of my PDF?', 'Yes, the PDF to Images tool renders pages using high-DPI canvas algorithms to guarantee crisp text and sharp visuals in both PNG and JPG formats.', 1),
(7, 'pdf-to-images', 'pdf-tools', 'Are my confidential documents uploaded to a remote server?', 'No! The PDF to Images conversion runs locally in your browser memory using PDF.js. Your document never leaves your machine.', 2),
(8, 'images-to-pdf', 'pdf-tools', 'Can I change the order of images before generating the PDF?', 'Yes, you can easily drag and drop image cards to arrange the pages in whatever sequence you desire.', 1),
(9, 'merge-pdf', 'pdf-tools', 'Is there a limit on how many PDF files I can merge?', 'You can merge multiple PDF documents simultaneously. The combined PDF will be available for instant download.', 1),

-- SEO FAQs
(10, 'xml-sitemap-generator', 'seo-tools', 'How do I submit the generated sitemap to Google?', 'Download your generated sitemap.xml file, upload it to the root directory of your website (e.g., https://yourdomain.com/sitemap.xml), and submit its URL inside Google Search Console.', 1),
(11, 'seo-analyzer', 'seo-tools', 'What does the SEO score represent?', 'The SEO score evaluates essential on-page factors including title tag presence and length, meta description, heading structure (H1-H6), image alt tags, and mobile viewport readiness.', 1),

-- Dev FAQs
(12, 'json-formatter', 'developer-tools', 'How does the JSON validator help me fix syntax errors?', 'If your JSON contains missing commas, invalid quotation marks, or syntax errors, the validator highlights the exact line and column number where the syntax breaks.', 1),
(13, 'qr-code-generator', 'developer-tools', 'Do the generated QR codes expire?', 'No! The QR codes generated on ToolsWallet are static QR codes containing the direct encoded data. They never expire and have no scan limits.', 1);

